mapper.select:
select * from ( select rownum rn, TMP.* from ( select n.note_no as noteNo, n.project_no as projectNo, n.note_writer_no as noteWriterNo, n.note_title as noteTitle, n.note_content as noteContent, n.note_ctime as noteCtime, n.note_utime as noteUtime from note n where n.project_no = #{projectNo}
and n.note_no < #{req.lastNo}
and instr(n.note_title, #{req.keyword}) > 0
and dbms_lob.instr(n.note_content, #{req.keyword}) > 0
and ( instr(n.note_title, #{req.keyword}) > 0 or dbms_lob.instr(n.note_content, #{req.keyword}) > 0 )
order by n.note_no desc ) TMP ) where rn between 1 and #{req.size}
